"""Short code generation and validation."""

from __future__ import annotations

import re
import secrets

ALPHABET = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ"
CUSTOM_CODE_RE = re.compile(r"^[0-9A-Za-z_-]{3,32}$")
RESERVED = {"api", "health", "static"}


def generate_code(length: int = 7) -> str:
    """Cryptographically random base62 code."""
    return "".join(secrets.choice(ALPHABET) for _ in range(length))


def is_valid_custom_code(code: str) -> bool:
    return bool(CUSTOM_CODE_RE.match(code)) and code.lower() not in RESERVED

"""SQLite-backed storage for short links."""

from __future__ import annotations

import sqlite3
import threading
import time
from dataclasses import dataclass


@dataclass(frozen=True)
class Link:
    code: str
    long_url: str
    created_at: float
    clicks: int


class Storage:
    """Thread-safe SQLite storage. Uses one connection per thread."""

    _SCHEMA = """
        CREATE TABLE IF NOT EXISTS links (
            code       TEXT PRIMARY KEY,
            long_url   TEXT NOT NULL,
            created_at REAL NOT NULL,
            clicks     INTEGER NOT NULL DEFAULT 0
        );
        CREATE INDEX IF NOT EXISTS idx_links_url ON links(long_url);
    """

    def __init__(self, path: str) -> None:
        self._path = path
        self._local = threading.local()
        with self._conn() as conn:
            conn.executescript(self._SCHEMA)

    def _conn(self) -> sqlite3.Connection:
        conn = getattr(self._local, "conn", None)
        if conn is None:
            conn = sqlite3.connect(self._path)
            conn.row_factory = sqlite3.Row
            conn.execute("PRAGMA journal_mode=WAL")
            self._local.conn = conn
        return conn

    def insert(self, code: str, long_url: str) -> bool:
        """Insert a link. Returns False if the code already exists."""
        try:
            with self._conn() as conn:
                conn.execute(
                    "INSERT INTO links (code, long_url, created_at) VALUES (?, ?, ?)",
                    (code, long_url, time.time()),
                )
            return True
        except sqlite3.IntegrityError:
            return False

    def get(self, code: str) -> Link | None:
        row = self._conn().execute(
            "SELECT * FROM links WHERE code = ?", (code,)
        ).fetchone()
        if row is None:
            return None
        return Link(row["code"], row["long_url"], row["created_at"], row["clicks"])

    def find_by_url(self, long_url: str) -> Link | None:
        row = self._conn().execute(
            "SELECT * FROM links WHERE long_url = ? LIMIT 1", (long_url,)
        ).fetchone()
        if row is None:
            return None
        return Link(row["code"], row["long_url"], row["created_at"], row["clicks"])

    def record_click(self, code: str) -> None:
        with self._conn() as conn:
            conn.execute(
                "UPDATE links SET clicks = clicks + 1 WHERE code = ?", (code,)
            )

    def delete(self, code: str) -> bool:
        with self._conn() as conn:
            cur = conn.execute("DELETE FROM links WHERE code = ?", (code,))
        return cur.rowcount > 0

"""REST API and redirect routes."""

from __future__ import annotations

import math
from urllib.parse import urlparse

from flask import Blueprint, current_app, jsonify, redirect, request, url_for

from .codes import generate_code, is_valid_custom_code

bp = Blueprint("shortener", __name__)

MAX_URL_LENGTH = 2048
MAX_CODE_ATTEMPTS = 5


def _storage():
    return current_app.extensions["storage"]


def _limiter():
    return current_app.extensions["limiter"]


def _client_key() -> str:
    return request.headers.get("X-Forwarded-For", request.remote_addr or "unknown") \
        .split(",")[0].strip()


def _error(status: int, message: str, **extra):
    body = {"error": message, **extra}
    return jsonify(body), status


def _validate_url(raw: str) -> str | None:
    """Return normalized URL, or None if invalid."""
    if not raw or len(raw) > MAX_URL_LENGTH:
        return None
    parsed = urlparse(raw)
    if parsed.scheme not in ("http", "https") or not parsed.netloc:
        return None
    return raw


def _link_json(link) -> dict:
    return {
        "code": link.code,
        "long_url": link.long_url,
        "short_url": url_for("shortener.follow", code=link.code, _external=True),
        "created_at": link.created_at,
        "clicks": link.clicks,
    }


@bp.before_request
def enforce_rate_limit():
    allowed, retry_after = _limiter().check(_client_key())
    if not allowed:
        resp, status = _error(429, "rate limit exceeded")
        resp.headers["Retry-After"] = str(math.ceil(retry_after))
        return resp, status
    return None


@bp.get("/health")
def health():
    return jsonify({"status": "ok"})


@bp.post("/api/shorten")
def shorten():
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return _error(400, "request body must be a JSON object")

    long_url = _validate_url(data.get("url", ""))
    if long_url is None:
        return _error(400, "invalid or missing 'url' (must be http/https)")

    storage = _storage()
    custom = data.get("custom_code")

    if custom is not None:
        if not isinstance(custom, str) or not is_valid_custom_code(custom):
            return _error(400, "invalid custom_code (3-32 chars: alphanumeric, - or _)")
        if not storage.insert(custom, long_url):
            return _error(409, "custom_code already in use")
        return jsonify(_link_json(storage.get(custom))), 201

    # Idempotent shortening: reuse existing code for the same URL.
    existing = storage.find_by_url(long_url)
    if existing is not None:
        return jsonify(_link_json(existing)), 200

    length = current_app.config["CODE_LENGTH"]
    for _ in range(MAX_CODE_ATTEMPTS):
        code = generate_code(length)
        if storage.insert(code, long_url):
            return jsonify(_link_json(storage.get(code))), 201
    return _error(500, "could not allocate a unique code")


@bp.get("/api/links/<code>")
def stats(code: str):
    link = _storage().get(code)
    if link is None:
        return _error(404, "unknown code")
    return jsonify(_link_json(link))


@bp.delete("/api/links/<code>")
def delete(code: str):
    if not _storage().delete(code):
        return _error(404, "unknown code")
    return "", 204


@bp.get("/<code>")
def follow(code: str):
    link = _storage().get(code)
    if link is None:
        return _error(404, "unknown code")
    _storage().record_click(code)
    return redirect(link.long_url, code=302)

